// $json is n8n's standard error payload.
const e = $input.first().json;
const wf = e.workflow || {};
const exec = e.execution || {};
const err = e.error || {};
const when = (exec.startedAt || new Date().toISOString()).slice(0, 19).replace('T', ' ');
const msg = [
  `n8n workflow FAILED: ${wf.name || 'unknown'}`,
  `When: ${when}`,
  `Execution: ${exec.id || 'n/a'}`,
  `Error: ${err.message || err.name || JSON.stringify(err).slice(0, 200)}`,
  exec.url ? `Open: ${exec.url}` : ''
].filter(Boolean).join('\n');
return [{ json: { msg, wfName: wf.name || 'unknown' } }];
